import csv
import json
from datetime import datetime

with open('CATALOG_CSV', 'r') as catalog_file, open('VALUES_CSV', 'r') as values_file:
    catalog = csv.DictReader(catalog_file)
    values = csv.DictReader(values_file)

zone_temp_max = {}

for row in catalog:
    if row['building_id'] == 'building_id_for_AHU02' and row['point_class'] == 'TemperatureAir':
        zone_temp_max[row['point_uri']] = float('-inf')

for row in values:
    if row['timeseries_id'] in zone_temp_max:
        dt = datetime.strptime(row['timestamp'], '%Y-%m-%d %H:%M:%S')
        if dt.hour == 11 and dt.day == 4 and dt.month == 1 and dt.year == 2018:\n            zone_temp_max[row['timeseries_id']] = max(zone_temp_max[row['timeseries_id']], float(row['value']))\n
answer = max(zone_temp_max, key=zone_temp_max.get)
print(json.dumps({'entity': answer}))
